using System.Globalization;
using System.Security.Cryptography;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Frameflow.Core;
using Frameflow.Media;

namespace Frameflow;
internal sealed class EncodeTestProgress(Action<EncodeProgress> callback):IProgress<EncodeProgress>{public void Report(EncodeProgress value)=>callback(value);}
internal static class EncodingTests
{
    internal static string FixtureFolder(string dir)=>Path.Combine(dir,"encoding fixture's [中文]");
    internal static string FixtureVideo(string dir)=>Path.Combine(FixtureFolder(dir),"input clip's [中文].mp4");
    internal static string FixtureAss(string dir)=>Path.Combine(FixtureFolder(dir),"styled.ass");
    internal static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
    internal static string StyledAss()
    {
        var d=SubtitleDocument.Parse(SubtitleDocument.New().Serialize().Replace("PlayResX: 1920","PlayResX: 640").Replace("PlayResY: 1080","PlayResY: 360"));var style=d.Styles.First();style.Set("Fontname","Arial");style.Set("Fontsize","36");style.Set("PrimaryColour","&H000000FF");style.Set("OutlineColour","&H00FFFFFF");style.Set("Outline","2");style.Set("Shadow","2");style.Set("Bold","-1");style.Set("MarginV","25");
        d.Add(1,3,"红色样式 RED");d.Add(2,4,@"{\an7\pos(40,35)\1c&H00FF00&\bord2}定位 GREEN");d.Add(5,10,@"{\an7\pos(60,115)\1c&HFF0000&\t(0,2500,\fs58)}BLUE 动画");d.Add(5,10,@"{\an7\pos(450,40)\1c&H00FFFF&\p1}m 0 0 l 100 0 100 50 0 50{\p0}");d.Add(0,12,"COMMENT MUST NOT BURN");d.Rows.Last().Comment=true;return d.Serialize()+"\r\n[Extra Metadata]\r\nopaque: retained\r\n";
    }
    internal static async Task FrameAsync(string input,string output,double time)
    {
        var p=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffmpeg"),["-hide_banner","-nostdin","-y","-ss",time.ToString(CultureInfo.InvariantCulture),"-i",input,"-frames:v","1","-an",output],null,CancellationToken.None,null,null,15);if(p.Exit!=0)throw new Exception(p.Error);
    }
    internal static (int Red,int Green,int Blue,int Yellow,int Bright) Colors(string file,int top=0,int bottom=360)
    {
        using var stream=File.OpenRead(file);var bitmap=BitmapFrame.Create(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);var b=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[b.PixelWidth*b.PixelHeight*4];b.CopyPixels(pixels,b.PixelWidth*4,0);int red=0,green=0,blue=0,yellow=0,bright=0;
        for(int y=top;y<Math.Min(bottom,b.PixelHeight);y++)for(int x=0;x<b.PixelWidth;x++){int p=(y*b.PixelWidth+x)*4;int B=pixels[p],G=pixels[p+1],R=pixels[p+2];if(R>100&&R>G*1.5&&R>B*1.5)red++;if(G>100&&G>R*1.5&&G>B*1.5)green++;if(B>100&&B>R*1.5&&B>G*1.5)blue++;if(R>100&&G>100&&B<80)yellow++;if(R>100||G>100||B>100)bright++;}return(red,green,blue,yellow,bright);
    }
    internal static void Run(string dir,Action<bool,string> check)=>Task.Run(()=>RunAsync(dir,check)).GetAwaiter().GetResult();
    static async Task RunAsync(string dir,Action<bool,string> check)
    {
        string folder=FixtureFolder(dir);Directory.CreateDirectory(folder);string input=FixtureVideo(dir),assFile=FixtureAss(dir),ass=StyledAss();File.WriteAllText(assFile,ass);string output=Path.Combine(folder,"burned-"+Guid.NewGuid().ToString("N")+".mp4");
        void Reject(Action run,string label){bool rejected=false;try{run();}catch(Exception){rejected=true;}check(rejected,label);}
        await BurnInEncoder.CheckEngineAsync(CancellationToken.None);check(true,"bundled FFmpeg actually exposes libass libx264 and AAC");
        if(!File.Exists(input)){var made=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffmpeg"),["-hide_banner","-nostdin","-n","-f","lavfi","-i","color=c=black:s=640x360:r=24:d=12","-f","lavfi","-i","sine=frequency=440:sample_rate=48000:duration=12","-c:v","libx264","-threads","2","-pix_fmt","yuv420p","-c:a","aac","-shortest",input],null,CancellationToken.None,null,null,30);check(made.Exit==0,"generated actual H264/AAC burn-in test source");}else check(true,"existing generated H264/AAC burn-in source reused");
        string original=Hash(input),originalAss=Hash(assFile);var facts=await BurnInEncoder.ProbeAsync(input,CancellationToken.None);check(facts.Width==640&&facts.Height==360&&facts.HasAudio&&Math.Abs(facts.Duration-12)<.1&&!facts.Hdr,"FFprobe reads actual video dimensions duration and audio");var r=new EncodeRequest(input,output,ass,Acceleration:EncodingAcceleration.CpuOnly);
        Reject(()=>BurnInEncoder.Validate(r with{Output=input}),"burn-in rejects source overwrite");Reject(()=>BurnInEncoder.Validate(r with{Output=assFile}),"burn-in requires MP4 output");Reject(()=>BurnInEncoder.Validate(r with{Input=input+"missing"}),"missing source rejected");Reject(()=>BurnInEncoder.Validate(r with{Quality=9}),"invalid quality rejected");Reject(()=>BurnInEncoder.Validate(r with{PreviewStart=-1}),"negative preview offset rejected");Reject(()=>BurnInEncoder.Validate(r with{Ass=SubtitleDocument.New().Serialize()}),"empty subtitles rejected instead of silent uncaptioned video");
        string sentinel=Path.Combine(folder,"existing.mp4");File.WriteAllText(sentinel,"preserve");Reject(()=>BurnInEncoder.Validate(r with{Output=sentinel}),"existing output rejected even when replacement was requested elsewhere");check(File.ReadAllText(sentinel)=="preserve","failed validation leaves existing output byte-identical");check(!BurnInEncoder.SuggestOutput(input).Equals(input,StringComparison.OrdinalIgnoreCase),"suggested output differs from source");
        var args=BurnInEncoder.Arguments(r,"temp.mp4");check(args.Contains(Path.GetFullPath(input))&&args[Array.IndexOf(args.ToArray(),"-vf")+1].Contains("snapshot.ass")&&!args.Any(x=>x.Contains("force_style")),"argument array protects Unicode apostrophe paths and preserves ASS styles without overrides");check(!args.Contains("-r")&&args.Contains("vfr")&&args.Contains("0:a:0?"),"encoding keeps timestamp cadence and optional original first audio track");var previewArgs=BurnInEncoder.Arguments(r with{PreviewStart=5,Audio=false},"temp.mp4");check(previewArgs.Contains("-an")&&previewArgs.Contains("10")&&previewArgs.Any(x=>x.Contains("PTS+5/TB")&&x.Contains("PTS-5/TB")),"preview offsets renderer clock to original subtitle times and can omit audio");
        string hdrJson="{\"streams\":[{\"codec_type\":\"video\",\"width\":1920,\"height\":1080,\"duration\":\"2\",\"color_transfer\":\"smpte2084\"}]}";check(BurnInEncoder.ParseProbe(hdrJson).Hdr,"HDR transfer metadata detected for explicit refusal");Reject(()=>BurnInEncoder.ParseProbe("{\"streams\":[{\"codec_type\":\"audio\"}]}"),"audio-only source is not treated as video");
        var progress=new List<double>();var encoded=await BurnInEncoder.EncodeAsync(r,new EncodeTestProgress(p=>progress.Add(p.Fraction)),CancellationToken.None);check(File.Exists(output)&&encoded.Video.Codec=="h264"&&encoded.Video.HasAudio&&encoded.Video.SubtitleStreams==0,"real encode writes H264 video plus audio with no soft subtitle stream");check(encoded.Video.Width==640&&encoded.Video.Height==360&&Math.Abs(encoded.Video.Duration-12)<.1,"burn-in preserves source dimensions and duration");check(progress.First()==0&&progress.Last()==1&&progress.All(x=>x>=0&&x<=1),"real progress reaches completion only after output verification");check(File.ReadAllText(encoded.LogPath).Contains("command_execution PID=")&&File.ReadAllText(encoded.LogPath).Contains("EXIT_STATUS: 0")&&encoded.FontLog.Contains("fontselect"),"encode log contains actual process exits commands and font selection");
        foreach(var (time,name) in new[]{(.2,"blank"),(1.5,"red"),(2.5,"green"),(5.2,"blue-small"),(7.6,"blue-large")})await FrameAsync(output,Path.Combine(folder,name+".png"),time);
        check(Colors(Path.Combine(folder,"blank.png")).Bright==0,"no subtitle pixels before cue and comments are not burned");check(Colors(Path.Combine(folder,"red.png"),240,360).Red>300,"ASS red style and bottom placement survive real video encode");check(Colors(Path.Combine(folder,"green.png"),20,120).Green>300,"inline green color and positioned top text survive real video encode");var small=Colors(Path.Combine(folder,"blue-small.png"),100,230);var large=Colors(Path.Combine(folder,"blue-large.png"),100,230);check(small.Blue>100&&large.Blue>small.Blue*1.2,"libass animated font-size override grows blue glyph pixels over time");check(Colors(Path.Combine(folder,"blue-small.png"),20,100).Yellow>2000,"ASS vector drawing survives libass burn-in");
        string preview=Path.Combine(folder,"preview-"+Guid.NewGuid().ToString("N")+".mp4");var pr=await BurnInEncoder.EncodeAsync(r with{Output=preview,PreviewStart=5,Audio=false},null,CancellationToken.None);check(!pr.Video.HasAudio&&Math.Abs(pr.Video.Duration-7)<.1,"preview clips at source end and honors no-audio option");await FrameAsync(preview,Path.Combine(folder,"preview-blue.png"),.2);check(Colors(Path.Combine(folder,"preview-blue.png"),100,230).Blue>100,"preview retains original ASS timing after seeking five seconds");
        string fontDir=Path.Combine(folder,"fonts custom's [字]");Directory.CreateDirectory(fontDir);string font=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts),"arial.ttf");check(File.Exists(font),"font-directory test uses actual installed Arial font");File.Copy(font,Path.Combine(fontDir,"custom.ttf"),true);var custom=await BurnInEncoder.EncodeAsync(r with{Output=Path.Combine(folder,"font-preview-"+Guid.NewGuid().ToString("N")+".mp4"),PreviewStart=11,FontDirectory=fontDir},null,CancellationToken.None);check(File.ReadAllText(custom.LogPath).Contains("FONT: ")&&Hash(Path.Combine(fontDir,"custom.ttf"))==Hash(font),"custom font folder with special characters is staged read-only and used by libass");
        string canceled=Path.Combine(folder,"canceled-"+Guid.NewGuid().ToString("N")+".mp4");using(var cancel=new CancellationTokenSource()){bool refused=false;try{await BurnInEncoder.EncodeAsync(r with{Output=canceled},new EncodeTestProgress(p=>{if(p.Text.StartsWith("已处理"))cancel.Cancel();}),cancel.Token);}catch(EncodeFailure e){refused=e.Canceled;}check(refused&&!File.Exists(canceled),"cancel during actual FFmpeg progress prevents final output commit");}
        check(Colors(Path.Combine(folder,"blue-large.png"),20,100).Yellow>2000,"ASS vector drawing remains visible alongside late animated text");
        string cadence=Path.Combine(folder,"vfr-"+Guid.NewGuid().ToString("N")+".mkv");
        var vfr=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffmpeg"),["-hide_banner","-nostdin","-n","-f","lavfi","-i","testsrc2=s=160x90:r=10:d=2","-vf","setpts=if(lt(N\\,10)\\,N\\,10+(N-10)*2)/(10*TB)","-fps_mode","vfr","-c:v","libx264","-threads","2",cadence],null,CancellationToken.None,null,null,20);
        check(vfr.Exit==0,"generated actual variable-frame-rate source without audio");
        var vfrResult=await BurnInEncoder.EncodeAsync(r with{Input=cadence,Output=Path.ChangeExtension(cadence,"mp4")},null,CancellationToken.None);
        async Task<double[]> Timestamps(string file){var p=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffprobe"),["-v","error","-select_streams","v:0","-show_entries","frame=best_effort_timestamp_time","-of","json",file],null,CancellationToken.None,null,null,20);if(p.Exit!=0)throw new Exception(p.Error);using var d=System.Text.Json.JsonDocument.Parse(p.Output);return d.RootElement.GetProperty("frames").EnumerateArray().Select(f=>double.Parse(f.GetProperty("best_effort_timestamp_time").GetString()!,CultureInfo.InvariantCulture)).ToArray();}
        var sourceTimes=await Timestamps(cadence);var outputTimes=await Timestamps(vfrResult.Output);
        check(sourceTimes.Length==20&&sourceTimes.Zip(sourceTimes.Skip(1),(a,b)=>Math.Round(b-a,3)).Distinct().Count()==2&&sourceTimes.Length==outputTimes.Length&&sourceTimes.Zip(outputTimes,(a,b)=>Math.Abs(a-b)<.003).All(v=>v),"real variable frame timestamps survive burn-in without duplicated or dropped frames");
        check(!vfrResult.Video.HasAudio,"optional source audio mapping accepts a real silent video");
        string odd=Path.Combine(folder,"odd-"+Guid.NewGuid().ToString("N")+".mkv");
        var oddMade=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffmpeg"),["-hide_banner","-nostdin","-n","-f","lavfi","-i","testsrc=s=161x91:r=10:d=2","-c:v","ffv1","-pix_fmt","bgr0",odd],null,CancellationToken.None,null,null,20);
        check(oddMade.Exit==0,"generated actual odd-dimension source");var oddResult=await BurnInEncoder.EncodeAsync(r with{Input=odd,Output=Path.ChangeExtension(odd,"mp4")},null,CancellationToken.None);
        check(oddResult.Video.Width==162&&oddResult.Video.Height==92,"odd dimensions gain at most one padded pixel for H264 compatibility");
        check(!Directory.GetDirectories(folder,".frameflow-encode-*").Any(),"success and cancellation clean only their owned staging directories");check(Hash(input)==original&&Hash(assFile)==originalAss,"real encodes previews and cancellation leave source video and subtitle bytes unchanged");
        var fail=await BurnInEncoder.RunAsync(BurnInEncoder.Tool("ffmpeg"),["-not-a-real-option"],null,CancellationToken.None);check(fail.Exit!=0&&fail.Error.Length>0,"actual FFmpeg error returns nonzero exit and literal diagnostic");
        File.WriteAllText(Path.Combine(folder,"results.json"),System.Text.Json.JsonSerializer.Serialize(new{input,assFile,output,preview,vfrSource=cadence,oddSource=odd,encoded.LogPath,sourceHash=original,assHash=originalAss,progress},new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));
    }
}
